def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    # Counts
    c_opp = sum(1 for i in range(n) if opp_at(i) == 'C')
    d_opp = n - c_opp

    # Detect simple always/defect patterns quickly
    if d_opp == 0:
        return 'C'
    if c_opp == 0:
        return 'D'

    # Last few opponent moves
    last = opp_at(n - 1)
    last2 = opp_at(n - 2) if n >= 2 else 'C'
    last3 = opp_at(n - 3) if n >= 3 else 'C'

    # Defection streak length at end
    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    # Cooperation streak length at end
    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    # If opponent has been mostly cooperative, cooperate but punish long defection runs
    coop_rate = c_opp / n

    # Endgame: last few rounds, try to exploit if opponent likely cooperates
    remaining = 100 - n
    if remaining <= 5:
        if coop_rate > 0.6 and streak_d == 0:
            return 'D'
        if coop_rate > 0.75:
            return 'D'
        return 'C'

    # Punish current defection streak
    if streak_d >= 2:
        return 'D'

    # Forgive after single defection sometimes
    if streak_d == 1:
        if coop_rate > 0.7 and streak_c >= 3:
            return 'C'
        if n >= 4 and opp_at(n - 3) == 'C' and opp_at(n - 4) == 'C':
            return 'C'
        return 'D'

    # If opponent is highly cooperative, cooperate
    if coop_rate >= 0.8:
        return 'C'

    # If opponent retaliation logic (TFT-like), mirror
    if n >= 2:
        # Check if opponent mirrored our previous move often
        mirror_score = 0
        for i in range(1, n):
            if opp_at(i) == me_at(i - 1):
                mirror_score += 1
        if mirror_score >= (n - 1) * 0.7:
            return me_at(n - 1)

    # Check if opponent alternates or uses patterns
    if n >= 6:
        alt_score = 0
        for i in range(1, n):
            if opp_at(i) != opp_at(i - 1):
                alt_score += 1
        if alt_score >= n - 2:
            # Alternating, predict next
            if last == 'C':
                return 'D'
            return 'C'

    # Tit-for-tat but slightly more forgiving
    if last == 'C':
        return 'C'
    else:
        # Forgive if opponent mostly cooperates
        if coop_rate > 0.6 and streak_d <= 1:
            return 'C'
        if coop_rate > 0.5 and rng.random() < 0.3:
            return 'C'
        return 'D'
